#!/usr/bin/env bash
# The hero cut into body parts for the bone rig, and a separate sword-throw sheet.
# Usage: MK_KEYS="key" tools/parts.sh [parts throw]   -> gen/raw_parts.png, gen/raw_throw.png
export MK_MODELS=${MK_MODELS:-"cx/gpt-image-2 cx/gpt-6-sol-image cx/gpt-image-1.5"}
MAN="a lean wandering swordsman about thirty with a short dark beard and long black hair tied back, wide conical woven bamboo hat, tattered dark indigo robe with a grey sash, loose charcoal-grey trousers, black cloth boots, a long vermilion red scarf, a straight double-edged jian sword with a plain dark hilt"
ST="Style: traditional Chinese ink wash painting (sumi-e), bold expressive black brush outlines, muted desaturated colours with the vermilion scarf as the only bright accent, cloth shaded in 3 to 4 tones. The whole sheet has a perfectly plain flat pure white #FFFFFF background, evenly lit like a scanned model sheet, every piece closed by a continuous black outline, wide gaps between pieces, nothing touching or overlapping, no ground, no shadow, no glow, no text, no numbers, no labels, no frame borders."
want() { [ ${#ARGS[@]} -eq 0 ] && return 0; for n in "${ARGS[@]}"; do [ "$n" = "$1" ] && return 0; done; return 1; }
ARGS=("$@")
one() {
  for try in 1 2 3 4 5; do
    if [ -s gen/raw_$1.png ] && python tools/white.py gen/raw_$1.png; then echo "$1 ok"; return; fi
    [ $try = 5 ] && { echo "$1 still bad"; return; }
    echo "$1 try $try"; tools/gen.sh "$1" "$2" "$ST"; sleep 2
  done
}
want parts && one parts "CUT-OUT PUPPET PARTS SHEET for 2D skeletal animation of $MAN, seen from the side facing RIGHT, every body part drawn SEPARATELY as its own piece like a paper puppet, with rounded ends at the joints so pieces can overlap when assembled. Exactly twelve pieces in two rows of six, all at the same scale. Row 1: 1 the HEAD with the conical hat, face in profile, hair tail and neck, 2 the TORSO from neck to hips with the robe top, collar and grey sash, no arms, no legs, no head, 3 the lower ROBE SKIRT panel that hangs from the sash to the knees, ragged hem, 4 the UPPER ARM in an indigo sleeve hanging straight down, shoulder at the top, 5 the FOREARM hanging straight down ending in a closed fist gripping nothing, elbow at the top, 6 a second FOREARM hanging straight down ending in an open flat hand, elbow at the top. Row 2: 7 the THIGH in loose grey trousers hanging straight down, hip at the top, 8 the SHIN with the black cloth boot hanging straight down, knee at the top, foot pointing right, 9 the SWORD alone pointing straight up, hilt at the bottom, 10 the long red SCARF laid out straight and flat, 11 the hair ponytail alone hanging down, 12 the sheathless sword hilt with a red tassel alone."
want throw && one throw "SPRITE SHEET of $MAN. Every frame shows the SAME character with identical face, costume, colours, proportions and size, full body, side-on three-quarter view facing RIGHT, strong exaggerated line of action, scarf and robe trailing. Twelve frames in three rows of four, frames evenly spaced with wide gaps. Row 1, THROWING THE SWORD like a javelin: 1 stepping forward with the sword raised beside the head pointing ahead, 2 cocking the arm far back with the body arched backward and weight on the back foot, 3 whipping the arm forward with the torso twisting and the sword about to leave the hand, 4 release: arm fully extended forward, empty open hand, the sword gone. Row 2, AFTER THE THROW and a QUICK FLICK: 5 follow-through leaning far forward on the front foot with the empty hand low, 6 recovering upright with the empty hands, 7 a second sword held low at the hip for a quick underarm flick, 8 the flick release with the arm swinging forward and the hand open. Row 3, CALLING THE SWORDS BACK: 9 two fingers raised before the face in a sword-calling gesture, 10 the arm swept up and back with the palm open and the robe lifting, 11 the hand closing on the hilt of a sword arriving from behind, 12 landing the caught sword into a ready stance."
want weapons && one weapons "CUT-OUT PUPPET PROPS SHEET for 2D skeletal animation: six ancient Chinese weapons drawn SEPARATELY, each standing straight up vertically, all at the same scale as each other, in one row with wide gaps. Each weapon has ONE small round pin hole drawn exactly where the hand grips it. 1 a long spear with a leaf-shaped iron blade at the top and a red tassel below the blade, pin hole at one third up the shaft, 2 a single curved saber blade pointing up with its hilt at the bottom, pin hole in the middle of the hilt, 3 a heavy long-handled iron mace with a round studded head at the top, pin hole near the bottom of the handle, 4 a large iron war fan fully OPEN like a half circle with the ribs gathered at the bottom, pin hole at the bottom pivot, 5 a tall recurve bow standing vertically with its string on the left side, pin hole in the middle of the grip, 6 a single arrow pointing up with fletching at the bottom, no pin hole."
echo PARTS DONE
